/**
 * ROTA2-DYNAMIC-TRAPS-01 — the census: every supported Route × mode over many
 * seeds, nothing hand-picked.
 *
 *   A  generation    1080 maps (3 Routes × 3 modes × 120 seeds, seeded per
 *                    map), each generated by production `generateMaze` AND
 *                    replayed attempt by attempt (instrumented-generator.mjs)
 *                    so every rejection is named: links, the link's shape,
 *                    trap distance and shortcut, distinct linked walls, retries
 *                    caused ONLY by the new trap-link gate, fallbacks (maps
 *                    settled in the recovery sweep), throws, invalid links (an
 *                    independent oracle, rota2-link-oracle.mjs) and how many
 *                    maps differ from what the v1 base generates for the seed.
 *   B  topology      every map, every reachable topology state — the link
 *                    closed/open × no Pickaxe wall or any wall the Explorer can
 *                    stand next to — through `inspectDynamicMazeState`: a
 *                    structural or topological softlock is any invalid state,
 *                    unreachable objective or cut-off cell.
 *   C  adversarial   the exact PRE_CHEST solver (rota2-dynamic-solver.mjs) on
 *                    a stratified sample, v1 model (link ignored) against the
 *                    Rota 2.0 model (link opens its wall), class by class.
 *   D  runtime       the REAL hook (route-runtime-harness.mjs) on a stratified
 *                    sample: the linked trap armed, the Hunter/Sentinel after
 *                    it, Pickaxe-before-trap and trap-before-Pickaxe, the
 *                    invariant inspector on every render, and every pre-Chest
 *                    transition held against the solver's exact support
 *                    (soundness of model C against production).
 *
 * Usage: node tools/validation/rota2-dynamic-traps-census.mjs [--check|--update]
 *        (about 20–30 minutes; `ROUTE_VALIDATION_OUT=<dir>` to write elsewhere)
 *
 * The verdict holds when: every map has exactly one legal link, the oracle
 * finds no invalid link, nothing throws, no topology state softlocks, the
 * solver is sound against the runtime, and every activation leaves a valid
 * state. Adversarial class changes are REPORTED, not hidden: the v1 game
 * already has pre-Chest unsolvable maps (ROTA-ADVERSARIAL-SOLVABILITY-03), and
 * the census says exactly where the mechanic moves a map between classes.
 */
import { loadInstrumented } from "./instrumented-generator.mjs";
import { cellKey, loadRouteRuntime, pathBetween, sameCell, walkableNeighbours } from "./route-runtime-harness.mjs";
import { independentLinkOffences, linkProfile } from "./rota2-link-oracle.mjs";
import { ACTIONS } from "./dynamic-solver.mjs";
import { buildDynamicContext, classifyMap, dynamicSuccessorSet, packDynamicState } from "./rota2-dynamic-solver.mjs";
import { openEvidence } from "./evidence.mjs";

const BASE = "9f8ebb5d8c0c747e68d8719e523ecab3ecbdab00";
const DIFFICULTIES = ["easy", "medium", "hard"];
const ROUTES = [1, 2, 3];
const MAPS_PER_COMBINATION = 120;
const SOLVER_PER_COMBINATION = 8;
const RUNTIME_PER_COMBINATION = 12;
const started = performance.now();

const keyToCell = (key) => {
  const [row, col] = key.split(",").map(Number);
  return { row, col };
};
const manhattan = (a, b) => Math.abs(a.row - b.row) + Math.abs(a.col - b.col);
const sortedKeys = (set) => [...set].sort();
const seedFor = (route, difficulty, index) => 9_200_000 + route * 10_000 + DIFFICULTIES.indexOf(difficulty) * 1_000 + index;
const v1Fields = (m) => JSON.stringify({ grid: m.grid, walls: sortedKeys(m.walls), playerStart: m.playerStart, guardianStart: m.guardianStart, exitPosition: m.exitPosition, collectibleStars: m.collectibleStars, traps: m.traps, chest: m.chest });
const tally = (object, key) => {
  object[key] = (object[key] ?? 0) + 1;
};
const log = (...m) => console.log(...m);

// =================================================================================================
// A — generation
// =================================================================================================
log("A  generation census");
const NOW = loadInstrumented({});
const V1 = loadInstrumented({ rev: BASE });
const generation = {
  maps: 0,
  throws: 0,
  v1Throws: 0,
  mapsWithExactlyOneLink: 0,
  trapsTotal: 0,
  trapsLinked: 0,
  distinctLinkedWallCells: 0,
  replayMatchesProduct: 0,
  attempts: 0,
  v1Attempts: 0,
  retriesCausedByTrapLinkGate: 0,
  mapsWithATrapLinkRetry: 0,
  fallbacks: 0,
  v1Fallbacks: 0,
  mapsDifferentFromV1: 0,
  invalidLinks: 0,
  shapes: {},
  trapDistance: {},
  shortcut: {},
  linkedTrapRank: {},
  perCombination: {},
};
const allMaps = [];
const wallCells = new Set();
const invalidExamples = [];
const differentExamples = [];
for (const route of ROUTES) {
  for (const difficulty of DIFFICULTIES) {
    const combo = { maps: 0, retriesCausedByTrapLinkGate: 0, fallbacks: 0, v1Fallbacks: 0, throws: 0, mapsDifferentFromV1: 0, distinctWalls: new Set() };
    for (let i = 0; i < MAPS_PER_COMBINATION; i += 1) {
      const seed = seedFor(route, difficulty, i);
      NOW.setSeed(seed);
      let map = null;
      try {
        map = NOW.API.generateMaze(difficulty, route);
      } catch {
        generation.throws += 1;
        combo.throws += 1;
      }
      NOW.setSeed(seed);
      const replay = NOW.replayGeneration({ difficulty, stage: route, capture: false });
      V1.setSeed(seed);
      const v1 = V1.replayGeneration({ difficulty, stage: route, capture: false });
      generation.maps += 1;
      combo.maps += 1;
      generation.attempts += replay.totalAttempts;
      generation.v1Attempts += v1.totalAttempts;
      if (v1.threw) generation.v1Throws += 1;
      if (replay.recoveryAttempts > 0 && !replay.threw) {
        generation.fallbacks += 1;
        combo.fallbacks += 1;
      }
      if (v1.recoveryAttempts > 0 && !v1.threw) {
        generation.v1Fallbacks += 1;
        combo.v1Fallbacks += 1;
      }
      const gateOnly = replay.attempts.filter((a) => a.certified === false && Array.isArray(a.finalGatesFailed) && a.finalGatesFailed.length === 1 && a.finalGatesFailed[0] === "trapLinksLegal").length;
      generation.retriesCausedByTrapLinkGate += gateOnly;
      combo.retriesCausedByTrapLinkGate += gateOnly;
      if (gateOnly > 0) generation.mapsWithATrapLinkRetry += 1;
      if (!map) continue;
      if (replay.map && v1Fields(replay.map) === v1Fields(map) && JSON.stringify(replay.map.trapLinks) === JSON.stringify(map.trapLinks)) generation.replayMatchesProduct += 1;
      if (!v1.map || v1Fields(v1.map) !== v1Fields(map)) {
        generation.mapsDifferentFromV1 += 1;
        combo.mapsDifferentFromV1 += 1;
        if (differentExamples.length < 5) differentExamples.push({ seed, route, difficulty, trapLinkRetries: gateOnly });
      }
      const links = map.trapLinks ?? [];
      if (links.length === 1) generation.mapsWithExactlyOneLink += 1;
      generation.trapsTotal += map.traps.length;
      generation.trapsLinked += links.length;
      const offences = independentLinkOffences(NOW.API, map);
      if (offences.length) {
        generation.invalidLinks += 1;
        if (invalidExamples.length < 5) invalidExamples.push({ seed, route, difficulty, offences });
      }
      const profile = linkProfile(NOW.API, map);
      if (profile) {
        wallCells.add(profile.wall);
        combo.distinctWalls.add(profile.wall);
        tally(generation.shapes, profile.shape);
        tally(generation.trapDistance, profile.trapDistance);
        tally(generation.shortcut, profile.shortcut);
        tally(generation.linkedTrapRank, profile.trapIndex);
      }
      allMaps.push({ seed, route, difficulty, map });
    }
    generation.perCombination[`${route}-${difficulty}`] = { ...combo, distinctWalls: combo.distinctWalls.size };
    log(`   R${route} ${difficulty}: ${combo.maps} maps · trap-link retries ${combo.retriesCausedByTrapLinkGate} · fallbacks ${combo.fallbacks} (v1 ${combo.v1Fallbacks}) · throws ${combo.throws} · differ from v1 ${combo.mapsDifferentFromV1}`);
  }
}
generation.distinctLinkedWallCells = wallCells.size;
generation.invalidExamples = invalidExamples;
generation.differentFromV1Examples = differentExamples;

// =================================================================================================
// B — every reachable topology state
// =================================================================================================
log("B  topology states");
const API = NOW.API;
/**
 * A legal resting state on the board: the Explorer at the start, the Hunter on its seat and the Sentinel on the
 * nearest zone cell that is not the linked trap — once a trap is armed no defender can stand on it (a defender on
 * a dormant trap blocks the Explorer from arming it at all: stepping there is a capture).
 */
const snapshotOf = (map, overrides) => {
  const zone = API.computePortalDefenceZone(map.playerStart, map.exitPosition, map.walls);
  const linkedTrap = (map.trapLinks ?? [])[0]?.trap ?? null;
  const post = zone.zone.find(
    (cell) => cellKey(cell) !== cellKey(map.exitPosition) && cellKey(cell) !== cellKey(map.playerStart) && cellKey(cell) !== cellKey(map.guardianStart) && cellKey(cell) !== linkedTrap,
  ) ?? API.createSentinelState(map, zone).position;
  return {
    mazeMap: map, player: map.playerStart, guardian: map.guardianStart, sentinel: post,
    collectedStars: [], triggeredTraps: [], chestOpened: false, rewardSelected: null, rewardSpent: false,
    brokenWall: null, trapOpenedWalls: [], status: "playing", ...overrides,
  };
};
const topology = { maps: 0, states: 0, pickaxeBeforeTrapStates: 0, trapBeforePickaxeStates: 0, softlocks: 0, invalid: 0, examples: [], portalZoneChanged: 0 };
for (const { seed, route, difficulty, map } of allMaps) {
  const link = (map.trapLinks ?? [])[0];
  if (!link) continue;
  topology.maps += 1;
  const opened = new Set(map.walls);
  opened.delete(link.mutation.wall);
  const zoneBefore = API.computePortalDefenceZone(map.playerStart, map.exitPosition, map.walls);
  const zoneAfter = API.computePortalDefenceZone(map.playerStart, map.exitPosition, opened);
  if (JSON.stringify(zoneBefore.zone.map(cellKey).sort()) !== JSON.stringify(zoneAfter.zone.map(cellKey).sort())) topology.portalZoneChanged += 1;
  for (const linkOpen of [false, true]) {
    const maze = linkOpen ? opened : map.walls;
    const reachable = API.getReachableDistances(map.playerStart, maze);
    const pickaxeWalls = [...maze].filter((w) => walkableNeighbours(keyToCell(w), maze).some((c) => reachable.has(cellKey(c))));
    for (const broken of [null, ...pickaxeWalls]) {
      const pickaxeFirstOnLink = broken === link.mutation.wall;
      const snapshot = snapshotOf(map, {
        triggeredTraps: linkOpen || pickaxeFirstOnLink ? [link.trap] : [],
        trapOpenedWalls: linkOpen ? [link.mutation.wall] : [],
        ...(broken !== null && { chestOpened: true, rewardSelected: "pickaxe", rewardSpent: true, brokenWall: broken }),
      });
      topology.states += 1;
      if (pickaxeFirstOnLink) topology.pickaxeBeforeTrapStates += 1;
      if (linkOpen && broken !== null) topology.trapBeforePickaxeStates += 1;
      const verdict = API.inspectDynamicMazeState(snapshot);
      const reach = API.getReachableDistances(map.playerStart, verdict.effectiveWalls);
      const cutOff = reach.size !== 81 - verdict.effectiveWalls.size;
      if (!verdict.valid) topology.invalid += 1;
      if (!verdict.valid || !verdict.topologicallySolvable || cutOff) {
        topology.softlocks += 1;
        if (topology.examples.length < 5) topology.examples.push({ seed, route, difficulty, linkOpen, broken, issues: verdict.issues, cutOff });
      }
    }
  }
}
log(`   ${topology.maps} maps · ${topology.states} states · softlocks ${topology.softlocks} · invalid ${topology.invalid}`);

// =================================================================================================
// C — exact adversarial classes, v1 model against the Rota 2.0 model
// =================================================================================================
log("C  exact PRE_CHEST solver, v1 vs Rota 2.0");
const short = (label) => ({ GUARANTEED_SOLVABLE_PRE_CHEST: "G", POSSIBLE_BUT_NOT_GUARANTEED_PRE_CHEST: "P", PROVED_UNSOLVABLE_PRE_CHEST: "U", INCONCLUSIVE_RESOURCE_LIMIT: "I", NOT_ANALYSED_ACCESSES_DIFFER: "N" })[label] ?? label;
const rank = { G: 0, P: 1, U: 2 };
const solver = { maps: 0, v1: {}, rota2: {}, transitions: {}, improved: 0, degraded: 0, unchanged: 0, inconclusive: 0, accessesDiffer: 0, degradedExamples: [], improvedExamples: [], note: "a class change needs every v1 strategy of that class to arm the linked trap" };
const solverSample = ROUTES.flatMap((route) => DIFFICULTIES.flatMap((difficulty) => allMaps.filter((m) => m.route === route && m.difficulty === difficulty).slice(0, SOLVER_PER_COMBINATION)));
for (const { seed, route, difficulty, map } of solverSample) {
  const v1 = classifyMap(map, difficulty, { dynamic: false });
  const r2 = classifyMap(map, difficulty, { dynamic: true });
  solver.maps += 1;
  tally(solver.v1, short(v1.label));
  tally(solver.rota2, short(r2.label));
  const pair = `${short(v1.label)}->${short(r2.label)}`;
  tally(solver.transitions, pair);
  if (r2.dctx.accessesDiffer) solver.accessesDiffer += 1;
  const a = rank[short(v1.label)];
  const b = rank[short(r2.label)];
  if (a === undefined || b === undefined) solver.inconclusive += 1;
  else if (b < a) {
    solver.improved += 1;
    if (solver.improvedExamples.length < 5) solver.improvedExamples.push({ seed, route, difficulty, pair });
  } else if (b > a) {
    // A v1 strategy that never arms the linked trap is a Rota 2.0 strategy too (same states, same maze), so a map
    // can only lose a class when EVERY v1 strategy of that class arms the linked trap. Reported, never hidden.
    solver.degraded += 1;
    solver.degradedExamples.push({ seed, route, difficulty, pair, linkedTrap: r2.dctx.link.trap, linkedWall: r2.dctx.link.mutation.wall });
  } else solver.unchanged += 1;
  log(`   R${route} ${difficulty} ${seed}: v1 ${short(v1.label)} (${v1.explored}) → rota2 ${short(r2.label)} (${r2.explored})`);
}

// =================================================================================================
// D — the real hook
// =================================================================================================
log("D  runtime scenarios on the real hook");
// A read-only recorder line at the top of the Hunter's policy: the walls each decision was given.
const RT = loadRouteRuntime({
  directDifficulty: true,
  transforms: {
    "src/games/escape-maze/route-defenders.ts": (source) => {
      const anchor = "  blockedForDefenders: Set<string> = EMPTY_BLOCKED,\n): GridPosition {\n";
      if (source.split(anchor).length !== 2) throw new Error("census: chooseGuardianMove anchor not found");
      return source.replace(anchor, `${anchor}  (globalThis as any).__rota2?.hunter.push({ walls });\n`);
    },
  },
});
const runtime = {
  maps: 0,
  activationsAttempted: 0,
  activations: 0,
  stepsOntoADefenderOnTheTrap: 0,
  wallOpenedOnActivation: 0,
  invalidAfterActivation: 0,
  hunterDecisionsAfterOpening: 0,
  hunterDecisionsOnStaleTopology: 0,
  defenderEnteredOpenedCell: 0,
  defenderRoutedThroughPassage: 0,
  pickaxeBeforeTrap: { attempted: 0, completed: 0, rerolled: 0, invalid: 0, noOp: 0 },
  trapBeforePickaxe: { attempted: 0, completed: 0, linkedWallOffered: 0, invalid: 0 },
  rendersInspected: 0,
  invalidRenders: 0,
  invalidPlayingRenders: 0,
  invalidTerminalRenders: {},
  terminalIssuesSameInV1: 0,
  terminalIssuesDifferentInV1: 0,
  invalidExamples: [],
  differential: { transitions: 0, unsound: 0, examples: [], afterOpening: 0 },
};
const trace = (RT.LAB.sb.__rota2 = { hunter: [] });

let margin = 1;
const walkStep = (run, target, avoidKeys) => {
  const g = run.state;
  const avoid = new Set(avoidKeys);
  if (g.mazeMap.chest && !g.chestOpened) avoid.add(cellKey(g.mazeMap.chest));
  avoid.add(cellKey(g.mazeMap.exitPosition));
  if (margin >= 0) for (const t of g.mazeMap.traps) avoid.add(cellKey(t));
  avoid.delete(cellKey(target));
  const reach = margin > 0 ? [g.guardian, g.sentinel, ...walkableNeighbours(g.guardian, g.walls), ...walkableNeighbours(g.sentinel, g.walls)] : [g.guardian, g.sentinel];
  const careful = new Set([...g.walls, ...avoid, ...reach.map(cellKey)]);
  careful.delete(cellKey(target));
  careful.delete(cellKey(g.player));
  let route = pathBetween(g.player, target, careful);
  if (!route) {
    const plain = new Set([...g.walls, ...avoid, cellKey(g.guardian), cellKey(g.sentinel)]);
    plain.delete(cellKey(target));
    route = pathBetween(g.player, target, plain);
  }
  if (!route || route.length < 2) return false;
  observedStep(run, route[1]);
  return true;
};
const walk = (run, target, avoidKeys = [], budget = 50) => {
  for (let i = 0; i < budget; i += 1) {
    const g = run.state;
    if (sameCell(g.player, target)) return true;
    if (g.status !== "playing" || g.rewardChoicePending) return false;
    if (!walkStep(run, target, avoidKeys)) return false;
  }
  return sameCell(run.state.player, target);
};
const walkBeside = (run, cell, avoidKeys = []) => {
  for (const n of walkableNeighbours(cell, run.state.walls).sort((a, b) => manhattan(a, run.state.player) - manhattan(b, run.state.player))) {
    if (walk(run, n, [cellKey(cell), ...avoidKeys])) return true;
    if (run.state.status !== "playing") return false;
  }
  return false;
};

// The solver's view of a render, for the differential check (pre-Chest only).
const numericOf = (g, dctx) => {
  const id = (p) => p.row * 9 + p.col;
  let lights = 0;
  g.mazeMap.collectibleStars.forEach((s, i) => {
    if (g.collectedSet.has(cellKey(s))) lights |= 1 << i;
  });
  let traps = 0;
  g.mazeMap.traps.forEach((t, i) => {
    if (g.triggeredTrapSet.has(cellKey(t))) traps |= 1 << i;
  });
  const t = g.sentinelTarget ? [...dctx.unionAccessIds].indexOf(id(g.sentinelTarget)) : -1;
  return { e: id(g.player), h: id(g.guardian), s: id(g.sentinel), t, c: g.sentinelCommitLeft, lights, traps };
};
let currentDctx = null;
function inspect(g) {
  runtime.rendersInspected += 1;
  if (!g.dynamicSolvability.valid) {
    runtime.invalidRenders += 1;
    if (g.status === "playing") runtime.invalidPlayingRenders += 1;
    else {
      for (const issue of g.dynamicSolvability.issues) tally(runtime.invalidTerminalRenders, `${g.status}:${issue}`);
      // The same state through the v1 base's own inspector: a terminal shape v1 already had says the same.
      const v1 = V1.API.inspectDynamicMazeState({
        mazeMap: g.mazeMap, player: g.player, guardian: g.guardian, sentinel: g.sentinel,
        collectedStars: [...g.collectedSet], triggeredTraps: [...g.triggeredTrapSet],
        chestOpened: g.chestOpened, rewardSelected: g.rewardSelected, rewardSpent: g.rewardSpent,
        brokenWall: g.brokenWall, status: g.status,
      });
      if (g.trapOpenedWalls.length === 0 && JSON.stringify(v1.issues) === JSON.stringify(g.dynamicSolvability.issues)) runtime.terminalIssuesSameInV1 += 1;
      else runtime.terminalIssuesDifferentInV1 += 1;
    }
    if (runtime.invalidExamples.length < 5) {
      runtime.invalidExamples.push({ status: g.status, issues: g.dynamicSolvability.issues, player: cellKey(g.player), guardian: cellKey(g.guardian), sentinel: cellKey(g.sentinel), chest: g.mazeMap.chest ? cellKey(g.mazeMap.chest) : null, trapOpenedWalls: g.trapOpenedWalls });
    }
  }
}
function observedStep(run, cell) {
  const before = run.state;
  const preChest = !before.chestOpened && before.rewardSelected === null;
  const dctx = currentDctx;
  let pre = null;
  if (preChest && dctx && !dctx.accessesDiffer) pre = numericOf(before, dctx);
  const delta = { row: cell.row - before.player.row, col: cell.col - before.player.col };
  const actionIndex = ACTIONS.findIndex((a) => a.row === delta.row && a.col === delta.col);
  const wallsBefore = before.walls;
  run.stepTo(cell);
  const after = run.state;
  inspect(after);
  if (pre && actionIndex >= 0 && !after.rewardChoicePending && after.turns === before.turns + 1) {
    const support = dynamicSuccessorSet(dctx, pre, actionIndex);
    runtime.differential.transitions += 1;
    if (after.trapOpenedWalls.length > 0 || wallsBefore !== after.walls) runtime.differential.afterOpening += 1;
    let sound;
    if (after.status === "lost") sound = Boolean(support?.hasLoss);
    else if (after.status === "won") sound = Boolean(support?.hasWin);
    else sound = Boolean(support) && support.states.includes(packDynamicState(dctx, numericOf(after, dctx)));
    if (!sound) {
      runtime.differential.unsound += 1;
      if (runtime.differential.examples.length < 5) runtime.differential.examples.push({ pre, actionIndex, status: after.status });
    }
  }
}

const runtimeSample = ROUTES.flatMap((route) => DIFFICULTIES.flatMap((difficulty) => allMaps.filter((m) => m.route === route && m.difficulty === difficulty).slice(0, RUNTIME_PER_COMBINATION)));
for (const { seed, route, difficulty } of runtimeSample) {
  runtime.maps += 1;
  // 1 · activation, then a few turns of the defenders on the opened maze
  for (const m of [1, 0, -1]) {
    margin = m;
    const run = RT.mount({ seed, difficulty, routeNumber: route });
    const link = run.state.trapLinks[0];
    currentDctx = buildDynamicContext(run.state.mazeMap, difficulty);
    inspect(run.state);
    if (m === 1) runtime.activationsAttempted += 1;
    const trap = keyToCell(link.trap);
    if (!walkBeside(run, trap)) continue;
    observedStep(run, trap);
    if (!sameCell(run.state.player, trap)) continue;
    // A step onto a defender standing on the trap is a capture and arms nothing (v1): not an activation.
    if (!run.state.triggeredTrapSet.has(link.trap)) {
      runtime.stepsOntoADefenderOnTheTrap += 1;
      continue;
    }
    runtime.activations += 1;
    const wall = link.mutation.wall;
    if (!run.state.walls.has(wall)) runtime.wallOpenedOnActivation += 1;
    if (!run.state.dynamicSolvability.valid) runtime.invalidAfterActivation += 1;
    // The defenders after the opening: every Hunter decision must see the wall open; do they use the passage?
    trace.hunter.length = 0;
    const wallCell = keyToCell(wall);
    const passage = new Set([wall, ...walkableNeighbours(wallCell, run.state.walls).map(cellKey)]);
    for (let i = 0; i < 10 && run.state.status === "playing" && !run.state.rewardChoicePending; i += 1) {
      const before = run.state;
      const target = i % 2 === 0 ? wallCell : before.mazeMap.playerStart;
      if (!walkStep(run, target, [])) break;
      const after = run.state;
      if (sameCell(after.guardian, wallCell) || sameCell(after.sentinel, wallCell)) runtime.defenderEnteredOpenedCell += 1;
      if (passage.has(cellKey(before.guardian)) && passage.has(cellKey(after.guardian)) && (sameCell(before.guardian, wallCell) || sameCell(after.guardian, wallCell))) runtime.defenderRoutedThroughPassage += 1;
    }
    runtime.hunterDecisionsAfterOpening += trace.hunter.length;
    runtime.hunterDecisionsOnStaleTopology += trace.hunter.filter((c) => c.walls.has(wall)).length;
    break;
  }
  margin = 1;
  currentDctx = null;
  // 2 · Pickaxe before trap
  {
    const run = RT.mount({ seed, difficulty, routeNumber: route });
    const link = run.state.trapLinks[0];
    const map = run.state.mazeMap;
    runtime.pickaxeBeforeTrap.attempted += 1;
    if (map.chest && walk(run, map.chest, [link.trap]) && run.state.rewardChoicePending) {
      run.choose("pickaxe");
      inspect(run.state);
      const wallCell = keyToCell(link.mutation.wall);
      if (run.state.status === "playing" && walkBeside(run, wallCell, [link.trap]) && run.state.breakTargets.some(({ cell }) => sameCell(cell, wallCell))) {
        run.break(wallCell);
        inspect(run.state);
        const trap = keyToCell(link.trap);
        if (run.state.status === "playing" && walkBeside(run, trap)) {
          const wallsBefore = new Set(run.state.walls);
          observedStep(run, trap);
          if (sameCell(run.state.player, trap)) {
            runtime.pickaxeBeforeTrap.completed += 1;
            const changed = sortedKeys(wallsBefore).join("|") !== sortedKeys(run.state.walls).join("|");
            if (changed) runtime.pickaxeBeforeTrap.rerolled += 1;
            else runtime.pickaxeBeforeTrap.noOp += 1;
            if (!run.state.dynamicSolvability.valid) runtime.pickaxeBeforeTrap.invalid += 1;
          }
        }
      }
    }
  }
  // 3 · trap before Pickaxe
  for (const m of [1, -1]) {
    margin = m;
    const run = RT.mount({ seed, difficulty, routeNumber: route });
    const link = run.state.trapLinks[0];
    const map = run.state.mazeMap;
    if (m === 1) runtime.trapBeforePickaxe.attempted += 1;
    const trap = keyToCell(link.trap);
    if (!map.chest || !walkBeside(run, trap)) continue;
    observedStep(run, trap);
    if (!sameCell(run.state.player, trap) || run.state.status !== "playing") continue;
    if (!walk(run, map.chest) || !run.state.rewardChoicePending) continue;
    run.choose("pickaxe");
    let offered = run.state.breakTargets.some(({ cell }) => cellKey(cell) === link.mutation.wall);
    for (let i = 0; i < 12 && run.state.status === "playing" && run.state.breakTargets.length === 0; i += 1) {
      const g = run.state;
      const nearWall = [...g.walls].flatMap((w) => walkableNeighbours(keyToCell(w), g.walls)).sort((a, b) => manhattan(a, g.player) - manhattan(b, g.player))[0];
      if (!nearWall || !walkStep(run, nearWall, [])) break;
      offered ||= run.state.breakTargets.some(({ cell }) => cellKey(cell) === link.mutation.wall);
    }
    if (run.state.status !== "playing" || run.state.breakTargets.length === 0) continue;
    run.break(run.state.breakTargets[0].cell);
    inspect(run.state);
    runtime.trapBeforePickaxe.completed += 1;
    if (offered) runtime.trapBeforePickaxe.linkedWallOffered += 1;
    if (!run.state.dynamicSolvability.valid) runtime.trapBeforePickaxe.invalid += 1;
    break;
  }
  margin = 1;
}
log(`   activations ${runtime.activations}/${runtime.activationsAttempted} · Pickaxe→trap ${runtime.pickaxeBeforeTrap.completed}/${runtime.pickaxeBeforeTrap.attempted} · trap→Pickaxe ${runtime.trapBeforePickaxe.completed}/${runtime.trapBeforePickaxe.attempted} · differential ${runtime.differential.transitions} (unsound ${runtime.differential.unsound})`);

// =================================================================================================
// verdict
// =================================================================================================
const checks = {
  everyMapHasExactlyOneLink: generation.mapsWithExactlyOneLink === generation.maps - generation.throws,
  noInvalidLink: generation.invalidLinks === 0,
  noThrow: generation.throws === 0,
  replayIsTheProduct: generation.replayMatchesProduct === generation.maps - generation.throws,
  fallbacksNotIncreased: generation.fallbacks <= generation.v1Fallbacks,
  portalZoneNeverChanges: topology.portalZoneChanged === 0,
  noTopologySoftlock: topology.softlocks === 0,
  solverSoundAgainstRuntime: runtime.differential.unsound === 0 && runtime.differential.transitions > 0,
  // A map the solver cannot finish within its budget is reported as INCONCLUSIVE, never counted as solved or as a
  // failure. Every map is modelled, a Sentinel door the opened maze adds included (`accessesDiffer`, reported).
  solverModelledEveryMap: !("N" in solver.rota2),
  noUnexplainedDegradation: solver.degradedExamples.every((d) => d.linkedTrap && d.linkedWall),
  everyActivationOpensAndStaysValid: runtime.activations > 0 && runtime.wallOpenedOnActivation === runtime.activations && runtime.invalidAfterActivation === 0,
  defendersNeverOnStaleTopology: runtime.hunterDecisionsOnStaleTopology === 0 && runtime.hunterDecisionsAfterOpening > 0,
  pickaxeBeforeTrapNeverRerolls: runtime.pickaxeBeforeTrap.rerolled === 0 && runtime.pickaxeBeforeTrap.completed > 0,
  trapBeforePickaxeNeverOffersTheOpenedWall: runtime.trapBeforePickaxe.linkedWallOffered === 0 && runtime.trapBeforePickaxe.completed > 0,
  // Every render while the Route is on is valid. A finished Route can hold a v1 terminal shape the inspector flags
  // (e.g. a capture stepping onto a defender who stands on the unopened Chest): reported, and each one must be what
  // the v1 base's own inspector says of the same state.
  everyPlayingRenderValid: runtime.invalidPlayingRenders === 0,
  terminalIssuesAreV1Shapes: runtime.terminalIssuesDifferentInV1 === 0,
};
const allPass = Object.values(checks).every(Boolean);
for (const [name, pass] of Object.entries(checks)) log(`${pass ? "PASS" : "FAIL"}  ${name}`);
log(`\nadversarial classes (pre-Chest, ${solver.maps} maps): v1 ${JSON.stringify(solver.v1)} → rota2 ${JSON.stringify(solver.rota2)} · transitions ${JSON.stringify(solver.transitions)}`);
log(allPass ? "ROTA2_DYNAMIC_TRAPS_CENSUS_OK" : "ROTA2_DYNAMIC_TRAPS_CENSUS_FAILED");

const EVIDENCE = openEvidence(process.env.ROUTE_VALIDATION_OUT ?? "docs/archive/rota2-dynamic-traps-01");
EVIDENCE.write(
  "census.json",
  {
    mission: "ROTA2-DYNAMIC-TRAPS-01",
    base: BASE,
    allPass,
    checks,
    sizes: { routes: ROUTES, difficulties: DIFFICULTIES, mapsPerCombination: MAPS_PER_COMBINATION, solverPerCombination: SOLVER_PER_COMBINATION, runtimePerCombination: RUNTIME_PER_COMBINATION },
    generation,
    topology,
    solver,
    runtime,
    run: { elapsedMs: Math.round(performance.now() - started) },
  },
  { metadata: ["run"] },
);
process.exitCode = EVIDENCE.finish({ ok: allPass });
